const visual = {
  prepare: function (input) {
    return [
      { kind: 'text', payload: '0' },
      { kind: 'text', payload: '1/5' },
      { kind: 'text', payload: '2/5' },
      { kind: 'text', payload: '1' }
    ];
  },
  render: function (input, metrics) {
    var W = input.viewport.widthDu;
    var H = input.viewport.heightDu;
    var y = H * 0.58;
    var x0 = W * 0.12;
    var x1 = W * 0.88;
    var step = (x1 - x0) / 5;
    var tick = Math.max(8, Math.min(18, H * 0.045));
    var dotR = Math.max(4, Math.min(8, W * 0.007));
    var axis = [['M', x0, y], ['L', x1, y]];
    var ticks = [];
    var i;
    for (i = 0; i <= 5; i = i + 1) {
      var tx = x0 + step * i;
      ticks.push(['M', tx, y - tick / 2]);
      ticks.push(['L', tx, y + tick / 2]);
    }
    var mark1 = visualSdk.circle(x0 + step, y, dotR);
    var mark2 = visualSdk.circle(x0 + step * 2, y, dotR);
    var guide1 = [['M', x0 + step, y - tick / 2 - 2], ['L', x0 + step, y - H * 0.16]];
    var guide2 = [['M', x0 + step * 2, y - tick / 2 - 2], ['L', x0 + step * 2, y - H * 0.16]];
    var labelY = y - H * 0.16 - 6;
    var paths = [
      { id: 'axis', commands: axis },
      { id: 'ticks', commands: ticks },
      { id: 'guide1', commands: guide1 },
      { id: 'guide2', commands: guide2 },
      { id: 'mark1', commands: mark1 },
      { id: 'mark2', commands: mark2 }
    ];
    return {
      schemaVersion: 1,
      sceneId: 'number-line-fifths',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: W, height: H },
      paths: paths,
      root: {
        type: 'group',
        children: [
          { type: 'path', pathId: 'axis', fill: '#26354a', stroke: { width: 2.5, cap: 'round' } },
          { type: 'path', pathId: 'ticks', fill: '#26354a', stroke: { width: 1.5, cap: 'round' } },
          { type: 'path', pathId: 'guide1', fill: '#9aa7b4', stroke: { width: 1 } },
          { type: 'path', pathId: 'guide2', fill: '#9aa7b4', stroke: { width: 1 } },
          { type: 'path', pathId: 'mark1', fill: '#d64541', stroke: { width: 1 } },
          { type: 'path', pathId: 'mark2', fill: '#d64541', stroke: { width: 1 } },
          { type: 'label', contentId: metrics[0].contentId, anchor: { x: x0, y: y + tick + 8 }, hAlign: 'center', vAlign: 'top', color: '#26354a' },
          { type: 'label', contentId: metrics[3].contentId, anchor: { x: x1, y: y + tick + 8 }, hAlign: 'center', vAlign: 'top', color: '#26354a' },
          { type: 'label', contentId: metrics[1].contentId, anchor: { x: x0 + step, y: labelY }, hAlign: 'center', vAlign: 'bottom', color: '#d64541' },
          { type: 'label', contentId: metrics[2].contentId, anchor: { x: x0 + step * 2, y: labelY }, hAlign: 'center', vAlign: 'bottom', color: '#d64541' }
        ]
      }
    };
  }
};
